$html = @'
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>User Portal</title><style>body{margin:0;background:#f4f7fb;font-family:Inter,system-ui;color:#10233f}.top{background:linear-gradient(135deg,#102a56,#2563eb);color:#fff;padding:28px 6%}.wrap{max-width:1100px;margin:auto;padding:28px 6%}.card{background:#fff;border:1px solid #dfe6f0;border-radius:16px;padding:22px;margin-bottom:18px;box-shadow:0 8px 24px #10233f0d}button{background:#2563eb;color:#fff;border:0;border-radius:9px;padding:12px 16px;font-weight:800;cursor:pointer}.muted{color:#667085}.ticket{border-top:1px solid #e4e7ec;padding:16px 0}.ticket:first-child{border-top:0}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef4ff;color:#175cd3;font-size:12px;font-weight:800}</style></head><body><header class="top"><h1 id="welcome">User Portal</h1><p>Submit and track your IT support tickets.</p></header><main class="wrap"><div class="card"><h2>Open a ticket</h2><p class="muted">Describe your problem and n8n will assign the department, priority, and SLA.</p><a href="/create-ticket"><button>Create new ticket</button></a></div><div class="card"><h2>My tickets</h2><div id="tickets">Loading tickets...</div></div></main><script>const token=sessionStorage.getItem('token');if(!token)location.href='/login';const headers={Authorization:'Bearer '+token};async function load(){const me=await fetch('/api/auth/me',{headers}),mj=await me.json();if(!mj.user||mj.user.role!=='user'){location.href='/dashboard/';return}welcome.textContent='Welcome, '+mj.user.full_name;const r=await fetch('/api/tickets',{headers}),d=await r.json();if(!d.tickets.length){tickets.innerHTML='<p class="muted">No tickets yet.</p>';return}tickets.innerHTML=d.tickets.map(t=>`<article class="ticket"><strong>${t.ticket_id}</strong> · ${t.title}<br><span class="badge">${t.status}</span> <span class="badge">${t.priority||'Normal'}</span><p class="muted">Department: ${t.department} · Due: ${t.due_at?new Date(t.due_at).toLocaleString():'-'}</p><button onclick="showComments('${t.ticket_id}')">View comments</button><div id="comments-${t.ticket_id}"></div></article>`).join('')}async function showComments(id){const r=await fetch('/api/tickets/comments?ticket_id='+encodeURIComponent(id),{headers}),d=await r.json();document.getElementById('comments-'+id).innerHTML=d.comments.length?d.comments.map(c=>`<p class="muted">${c.comment}</p>`).join(''):'<p class="muted">No comments yet.</p>'}load();</script></body></html>
'@
Set-Content dashboard/user.html $html -NoNewline
